namespace Jenin.FontAwesome.Blazor.Tests.Subsetting;

/// <summary>
/// Golden tests for the checked-in sprite fixture (<c>tests/e2e/fixtures/fa-sprite</c>,
/// generated by <c>eng/fa_sprite.py</c> from its <c>used-icons.json</c> manifest). They pin the
/// emitted symbols, the report numbers, and the no-JS contract the e2e render proof relies on.
/// </summary>
[TestClass]
public class FontAwesomeSpriteTests {
    private const string FIXTURE_DIR = "tests/e2e/fixtures/fa-sprite";
    private const string FIXTURE_SPRITE = "fa-sprite.svg";
    private const string FIXTURE_REPORT = "report.json";

    private static readonly string[] _expectedSymbols = ["fa-solid-camera", "fa-brands-youtube"];

    private static string RepoRoot() {
        var directory = new DirectoryInfo(AppContext.BaseDirectory);

        while(directory is not null && !File.Exists(Path.Combine(directory.FullName, "Jenin.FontAwesome.Blazor.slnx"))) {
            directory = directory.Parent;
        }

        directory.Should().NotBeNull("Could not locate the repository root (Jenin.FontAwesome.Blazor.slnx).");

        return directory!.FullName;
    }

    private static string FixturePath(string name) => Path.Combine(RepoRoot(), FIXTURE_DIR, name);

    private static JsonDocument FixtureReport() {
        using var stream = File.OpenRead(FixturePath(FIXTURE_REPORT));

        return JsonDocument.Parse(stream);
    }

    [TestMethod]
    [TestCategory("Subsetting")]
    public void FixtureCoversExactlyItsManifest() {
        using var report = FixtureReport();
        var root = report.RootElement;

        root.GetProperty("used_count").GetInt32().Should().Be(2);
        root.GetProperty("symbols").GetInt32().Should().Be(2);
        root.GetProperty("missing_names").GetArrayLength().Should().Be(0);
        root.GetProperty("dynamic_warnings").GetArrayLength().Should().Be(0);
    }

    [TestMethod]
    [TestCategory("Subsetting")]
    public void SpriteContainsSizedSymbolsWithCurrentColorFill() {
        var sprite = File.ReadAllText(FixturePath(FIXTURE_SPRITE));

        foreach(var id in _expectedSymbols) {
            sprite.Should().Contain($"<symbol id=\"{id}\" viewBox=\"0 0 512 512\">");
        }

        sprite.Should().Contain("fill=\"currentColor\"");
        sprite.Contains("<script", StringComparison.Ordinal).Should().BeFalse();
    }

    [TestMethod]
    [TestCategory("Subsetting")]
    public void SpriteStaysSmall() {
        var bytes = new FileInfo(FixturePath(FIXTURE_SPRITE)).Length;

        (bytes > 0).Should().BeTrue("The fixture sprite must not be empty.");
        (bytes < 20_000).Should().BeTrue($"The two-glyph fixture sprite should stay tiny (was {bytes} B).");
    }
}
